contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit1, uint256 deposit2) public {
        // Bound deposits to avoid overflow in balance sum and contract balance
        deposit1 = bound(deposit1, 0, 1e36);
        deposit2 = bound(deposit2, 0, 1e36);
        address alice = address(0x1000);

        // First deposit from Alice
        vm.deal(alice, deposit1);
        vm.prank(alice);
        c.addToBalance{value: deposit1}();

        // Withdraw Alice's balance to reset her balance to 0
        vm.prank(alice);
        c.withdrawBalance();

        // Second deposit from Alice — in reference, adds msg.value; in mutant, sets to msg.value
        vm.deal(alice, deposit2);
        vm.prank(alice);
        c.addToBalance{value: deposit2}();

        // Invariant: sum of all user balances via getBalance >= contract balance.
        // After withdrawal, contract holds only the second deposit (minus gas, but gas negligible for invariant).
        // Reference: Alice's balance = deposit2 => sum = deposit2 >= address(c).balance (~ deposit2).
        // Mutant: Alice's balance = deposit2, same, but wait - after withdrawal, contract balance is exactly deposit2,
        // and Alice's balance = deposit2, so sum >= balance holds. The invariant must break elsewhere.
        // Let's refine: if another user deposits in between, the mutant sets their balance to msg.value, potentially
        // making sum less than total deposits if a previous user's balance was overwritten.
        // We need to show sum of balances < contract balance. Use two different depositors.
    }
}

