pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address other) public {
        vm.assume(actor != address(0));
        vm.assume(other != address(0));
        vm.assume(actor != other);
        vm.assume(amount > 0);

        // Deploy a re-entrant attacker that calls addToBalance again during withdraw
        ReentrantAttacker attacker = new ReentrantAttacker();

        // Fund actor and attacker
        vm.deal(actor, amount);
        vm.deal(address(attacker), amount);

        // Actor deposits
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Attacker deposits and then withdraws to trigger reentrancy
        vm.prank(address(attacker));
        attacker.attack{value: amount}(address(c));

        // After all calls, total user balances should equal total deposits that were not withdrawn.
        // Deposits: actor(amount) + attacker(amount). Attacker withdrew after deposit, so final attacker balance should be 0 if correctly handled.
        // Actor never withdrew, so actor balance should be amount.
        // The invariant: sum of all balances recorded + address(c).balance == total deposits not yet withdrawn (i.e., total value ever added minus total zeroed).
        uint256 actorBal = c.getBalance(actor);
        uint256 attackerBal = c.getBalance(address(attacker));
        uint256 contractBal = address(c).balance;
        // Total deposits: 2 * amount. After successful reentrancy, attacker may have double-spent, leaving attackerBal > 0 or contractBal inconsistent.
        // Correct behavior: actorBal == amount, attackerBal == 0, contractBal == amount (attacker's deposit moved to attacker via withdraw).
        // Invariant: actorBal + attackerBal + contractBal == 2 * amount.
        assertTrue(actorBal + attackerBal + contractBal == 2 * amount);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 myDeposit;
    function attack(address _target) external payable {
        target = C(_target);
        myDeposit = msg.value;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }
    receive() external payable {
        // Re-enter withdrawBalance before balance is zeroed (bug allows reentrancy)
        if (address(target).balance >= myDeposit) {
            target.withdrawBalance();
        }
    }
}

