contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint8 iterations) public {
        // Bound iterations to keep fuzzing practical while exploring reentrant depth
        iterations = uint8(bound(iterations, 1, 10));
        // Bound amount to avoid overflow in vm.deal (total for attacker would be amount * iterations)
        amount = bound(amount, 0, type(uint256).max / 100);

        // Deploy an adversarial re-entrant attacker helper
        Attacker attacker = new Attacker(c);
        address attackerAddress = address(attacker);

        // Fund attacker with enough ether for all iterations
        vm.deal(attackerAddress, amount * iterations);

        // Execute multiple addToBalance calls from the attacker, which may reenter
        vm.startPrank(attackerAddress);
        for (uint8 i = 0; i < iterations; i++) {
            attacker.attack{value: amount}();
        }
        vm.stopPrank();

        // The general rule: the recorded balance of the attacker should exactly match
        // the total ether they sent through addToBalance. In the reference contract,
        // the nonReentrant modifier prevents reentrancy, so balance == amount * iterations.
        // In the buggy contract, reentrant calls can double-count or distort the balance,
        // causing a mismatch.
        uint256 expectedBalance = amount * iterations;
        uint256 actualBalance = c.getBalance(attackerAddress);
        assertTrue(actualBalance == expectedBalance);
    }
}

