import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2 - 1);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawBalance();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}

