pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount1, uint256 withdrawAmount2) public {
        // Bound amounts to reasonable range to avoid overflow and ensure contract has enough ETH
        depositAmount = bound(depositAmount, 0.1 ether, 100 ether);
        withdrawAmount1 = bound(withdrawAmount1, 0, depositAmount);
        withdrawAmount2 = bound(withdrawAmount2, 0, withdrawAmount1);

        // Deploy two distinct users
        address userA = address(0x1000);
        address userB = address(0x2000);

        // UserA deposits
        vm.deal(userA, depositAmount);
        vm.prank(userA);
        c.addToBalance{value: depositAmount}();

        // UserB deposits the same amount
        vm.deal(userB, depositAmount);
        vm.prank(userB);
        c.addToBalance{value: depositAmount}();

        // UserA withdraws part of their balance
        uint256 userABalanceBefore = c.getBalance(userA);
        if (userABalanceBefore > 0) {
            require(withdrawAmount1 <= userABalanceBefore, "withdrawAmount1 too large");
            vm.prank(userA);
            // First, force the contract to have enough ETH by ensuring userB deposited
            // Contract already has userA and userB deposits
            // We'll manipulate userA's balance to match withdrawAmount1 by depositing exact difference
            // Actually, we need to ensure userA's balance is at least withdrawAmount1
            // Since userA deposited depositAmount, and we bounded withdrawAmount1 <= depositAmount, it's fine
            // But the contract's total userBalance tracks the sum; we must not break the accounting manually.
            // We'll simply withdraw from userA: we need to set msg.sender to userA and call withdrawBalance
            // However, withdrawBalance sends the full userBalance[userA] to userA.
            // To fuzz the withdrawal amount, we need a different approach: we can use an adversarial helper that can call withdrawBalance and then forward funds.
            // Because the existing function withdrawBalance takes no arguments and sends the full balance, we cannot directly fuzz the withdrawal amount.
            // To fuzz the withdrawal amount, we must use a different function or adjust the balance first.
            // The invariant is about the sum of balances vs contract ETH. We'll simply make userA withdraw their full balance.
            // But we need to fuzz amounts. So we can first make userA deposit exactly withdrawAmount1 by resetting balance via a withdrawal and redeposit.
            // Wait, we cannot reset balance without withdrawing first.
            // Alternative: Use userA to deposit withdrawAmount1, then withdraw all. But we need fuzzed amounts.
            // Let's change approach: we'll let the fuzzer choose depositAmount for userA, then withdrawAmount1 for userA (must be <= depositAmount).
            // To withdraw a specific amount, we need a function that sends a specific amount; withdrawBalance always sends full balance.
            // Therefore, we cannot directly fuzz the withdrawal amount using the existing interface.
            // The invariant "sum of userBalances == address(c).balance" must hold after any sequence of allowed operations.
            // We'll perform operations: deposit by userA (fuzzed amount), deposit by userB (same amount), withdraw by userA (full amount), then check invariant.
            // The bug is that after withdrawal, userA's balance is not zeroed. So the sum of balances will be higher than the actual ETH left.
            // To trigger the difference, we just need userA to withdraw. After withdrawal, userA's balance is unchanged (bug) while ETH decreased.
            // So the invariant breaks immediately after one withdrawal.

            // Perform withdrawal
            uint256 ethBefore = address(c).balance;
            vm.prank(userA);
            c.withdrawBalance();
            uint256 ethAfter = address(c).balance;

            // Check invariant: sum of all userBalances (only userA and userB have non-zero) must equal contract ETH balance
            uint256 sumBalances = c.getBalance(userA) + c.getBalance(userB);
            assertTrue(sumBalances == ethAfter);
        } else {
            // If userA has zero balance, skip (shouldn't happen due to bounds)
            assertTrue(true);
        }
    }
}

