pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 otherAmount) public {
        // Ensure amounts are reasonable
        amount = bound(amount, 1, type(uint256).max / 2);
        otherAmount = bound(otherAmount, 1, type(uint256).max / 2);
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        // First withdrawal should succeed
        vm.prank(caller);
        try c.withdrawBalance() {
            // Second withdrawal must fail on reference (balance zeroed) but succeed on buggy (balance unchanged)
            vm.deal(caller, otherAmount);
            vm.prank(caller);
            try c.withdrawBalance() {
                // If we reach here, second withdrawal succeeded -> buggy behavior
                assertTrue(false, "Second withdrawal should have reverted");
            } catch {
                assertTrue(true);
            }
        } catch {
            // First withdrawal failed, skip this run
            assertTrue(true);
        }
    }
}
// No adversarial helper needed; the difference manifests through the contract's own state.
